if (n == 0) return std::complex<double>(1.0, 0.0);
double log_factorial = 0.0;
for (unsigned long i = 1; i <= n; ++i) {
    log_factorial += std::log(static_cast<double>(i));
}
if (n < 100) {
    std::complex<double> numerator = std::pow(alpha, static_cast<int>(n));
    double denominator = std::sqrt(std::exp(log_factorial));
    return numerator / denominator;
} else {
    double log_n = std::log(static_cast<double>(n));
    double stirling_log_factorial = n * log_n - n + 0.5 * std::log(2.0 * M_PI * n) + 1.0 / (12.0 * n);
    double log_norm = 0.5 * stirling_log_factorial;
    double log_magnitude = std::abs(alpha) * std::cos(std::arg(alpha)) * n - log_norm;
    double phase = std::arg(alpha) * n;
    double magnitude = std::exp(log_magnitude);
    return std::complex<double>(magnitude * std::cos(phase), magnitude * std::sin(phase));
}

